import{z as o,x as s,o as A,c as d,q as l,j as i,D as a,d as B,s as r,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"概念漂移的检测","description":"","frontmatter":{"title":"概念漂移的检测","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-drift-detection.md","filePath":"llm/continual-drift-detection.md","lastUpdated":1791413859000}'),D={name:"llm/continual-drift-detection.md"};function p(m,E,C,F,c,h){const t=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="概念漂移的检测" tabindex="-1">概念漂移的检测 <a class="header-anchor" href="#概念漂移的检测" aria-label="Permalink to &quot;概念漂移的检测&quot;">​</a></h1><div class="epigraph"><p>持续学习系统最难的不是学，而是决定何时学；更新该由证据触发，不该由日历触发。</p><footer>—— 据 Gama 等 2014（漂移综述）、Bifet 与 Gavaldà 2007（ADWIN）整理</footer></div><p><a href="/llm/continual-test-time-training">上一课</a>把适配压进单次请求。从本课起视角反过来：生产环首先要回答的不是「怎么更新」，而是「要不要更新、现在吗」。漂移检测就是这个触发器：从流量里辨认「世界变了」的证据，把更新从排班变成响应。检测做得糙，两个极端都会出现——永不触发，模型悄悄过期；天天触发，警报成了狼来了。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线上指标变差有三种死因，处置完全不同。世界变了（概念漂移）：用户群、语言、任务组合移动，模型没变但不再合身。模型变了（回归）：昨天的更新本身坏了。管线变了：分词、模板、上游服务的表面改动。混在一起时，「指标降了就回滚重训」会同时做错三件事：漏掉坏版本、白训一轮、真漂移淹没在噪声里。缺口是可分离的证据链。</p><h3 id="漂移的三层" tabindex="-1">漂移的三层 <a class="header-anchor" href="#漂移的三层" aria-label="Permalink to &quot;漂移的三层&quot;">​</a></h3><p>输入分布漂移（协变量漂移）：查询的 embedding 分布、语言构成、长度、领域占比移动。输出分布漂移：回答长度、拒答率、格式崩坏率变化，多半是输入先动了。性能漂移（概念漂移的严格义）：同样的输入，对的输出变了——用户不再接受旧答案，或新法规改判对错。三层移动有经验规律：输入先动，输出跟着，性能最后；只监控最后一层，报警时已晚了几个周期。</p><p><span class="marginnote">ADWIN（Bifet 与 Gavaldà 2007）在单流上维护变长窗口，均值差超界即报新窗口并收缩旧窗口；Page-Hinkley 更早，是累积和检验的老牌做法。两者都只处理一维流，嵌入分布要先用 MMD 一类双样本检验压成标量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监控按三层布点。输入层：对查询嵌入按天/周做双样本检验，对领域占比做份额监控。输出层：长度、拒答率、格式错误率做带滞后阈值的控制图——超阈值持续 \\(k\\) 个窗口才报，单点不报。性能层：固定探针电池加滚动偏好胜率。证据链的分离装置是一个<strong>冻结影子模型</strong>：线上一直挂一份钉死版本的模型跑同样探针。探针成绩与影子同降，是世界或管线变了；影子稳而线上降，是最近更新回归——这一刀把最难分的两种死因切开。</p><p><span class="marginnote">直觉类比：冻结影子模型就像药物试验里的安慰剂对照组——成分（版本）完全不变，经历同样的环境（同样的探针题）。病人（线上模型）和对照组同时变差，说明是环境变了（世界变了）；只有病人变差，才是药（新版本）的副作用。没有对照组，你永远说不清该怪世界还是怪自己上周的更新。</span></p>',11)),(A(),i(n,null,{default:a(()=>[r(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STREAM%5B%22%E7%BA%BF%E4%B8%8A%E6%B5%81%E9%87%8F%22%5D%20--%3E%20IN%5B%22%E8%BE%93%E5%85%A5%E5%B1%82%E7%9B%91%E6%8E%A7%EF%BC%9A%E5%B5%8C%E5%85%A5%E5%8F%8C%E6%A0%B7%E6%9C%AC%E6%A3%80%E9%AA%8C%22%5D%0A%20%20STREAM%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E5%B1%82%E7%9B%91%E6%8E%A7%EF%BC%9A%E9%95%BF%E5%BA%A6%2F%E6%8B%92%E7%AD%94%E7%8E%87%E6%8E%A7%E5%88%B6%E5%9B%BE%22%5D%0A%20%20STREAM%20--%3E%20PERF%5B%22%E6%80%A7%E8%83%BD%E5%B1%82%E7%9B%91%E6%8E%A7%EF%BC%9A%E6%8E%A2%E9%92%88%2B%E6%BB%9A%E5%8A%A8%E8%83%9C%E7%8E%87%22%5D%0A%20%20IN%20--%3E%20DET%5B%22%E6%BC%82%E7%A7%BB%E6%A3%80%E6%B5%8B%E5%99%A8%EF%BC%9A%E6%BB%9E%E5%90%8E%E9%98%88%E5%80%BC%22%5D%0A%20%20OUT%20--%3E%20DET%0A%20%20PERF%20--%3E%20DET%0A%20%20DET%20--%3E%7C%E6%8A%A5%E8%AD%A6%7C%20SHADOW%7B%22%E5%86%BB%E7%BB%93%E5%BD%B1%E5%AD%90%E6%A8%A1%E5%9E%8B%E5%90%8C%E9%99%8D%E5%90%97%3F%22%7D%0A%20%20SHADOW%20--%3E%7C%E6%98%AF%7C%20WORLD%5B%22%E4%B8%96%E7%95%8C%2F%E7%AE%A1%E7%BA%BF%E5%8F%98%E4%BA%86%EF%BC%9A%E6%9F%A5%E5%9B%A0%EF%BC%8C%E8%AF%84%E4%BC%B0%E6%9B%B4%E6%96%B0%22%5D%0A%20%20SHADOW%20--%3E%7C%E5%90%A6%7C%20REG%5B%22%E7%BA%BF%E4%B8%8A%E5%9B%9E%E5%BD%92%EF%BC%9A%E5%9B%9E%E6%BB%9A%E6%9C%80%E8%BF%91%E5%8F%91%E5%B8%83%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"统计设定决定报警质量。单流标量用 ADWIN 或 Page-Hinkley，窗口长度是时延与灵敏度的交换：短窗抓得快但抖动多，长窗稳但模型多带伤跑几周。多维检验要防多重检验——同时监控几十个切片，无漂移时也总有切片显著，要有家族级校正或只在预注册切片上报。滞后阈值与双侧回滞（触发与解除分开）是把统计工具变成可运维设备的两颗螺丝。",-1)),(A(),i(n,null,{default:a(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22%E7%AC%AC%200%20%E5%91%A8%3A%20%E7%94%A8%E6%88%B7%E7%BE%A4%E5%BC%80%E5%A7%8B%E8%BF%81%E7%A7%BB%22%5D%20--%3E%20T1%5B%22%E8%BE%93%E5%85%A5%E5%B1%82%E5%85%88%E6%8A%A5%E8%AD%A6%3Cbr%2F%3E%E5%B5%8C%E5%85%A5%E5%88%86%E5%B8%83%E7%A7%BB%E4%BD%8D%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E6%95%B0%E5%A4%A9%E5%90%8E%3A%20%E8%BE%93%E5%87%BA%E5%B1%82%E6%8A%A5%E8%AD%A6%3Cbr%2F%3E%E6%8B%92%E7%AD%94%E7%8E%87%20%2F%20%E6%A0%BC%E5%BC%8F%E9%94%99%E8%AF%AF%E7%8E%87%E5%8D%87%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E6%95%B0%E5%91%A8%E5%90%8E%3A%20%E6%80%A7%E8%83%BD%E5%B1%82%E6%89%8D%E6%8A%A5%E8%AD%A6%3Cbr%2F%3E%E6%8E%A2%E9%92%88%E5%88%86%E6%95%B0%E4%B8%8B%E6%BB%91%22%5D%0A%20%20T3%20--%3E%20LATE%5B%22%E5%8F%AA%E7%9B%AF%E6%80%A7%E8%83%BD%E5%B1%82%20%3D%20%E8%BF%9F%E5%88%B0%E6%95%B0%E5%91%A8%E7%9A%84%E6%8A%A5%E8%AD%A6%22%5D%0A%20%20T1%20--%3E%20EARLY%5B%22%E4%B8%89%E5%B1%82%E5%90%8C%E7%9C%8B%20%3D%20%E6%8F%90%E5%89%8D%E4%BB%8B%E5%85%A5%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><a href="/llm/live-benchmarks">动态基准与题库轮换</a>是检测的慢变量：新题不进训练、持续滚动，成绩下滑即能力过期信号；滚动基准看周与月，探针与控制图看小时与天。别把检测器本身污染掉——监控查询若也被训练，就绕回<a href="/llm/eval-contamination">训练-评测污染检测</a>的问题。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>检测不构成响应。没有预案的漂移报警只是图表：报警要绑定三选一的动作——回滚、评估更新、立案观察，并写明每档动作的负责人与时限。季节性是伪漂移的大头：工作日/周末、学期/假期、大促，都可以让输入层报警，处置不是重训而是把已知周期从报警里扣掉。慢漂移对检测器最难：单窗看不到显著差异，靠的是探针电池的趋势线而不是报警器。最后，漂移检测的结论必须可复核——把每次报警的窗口、统计量、当时的处置记进台账，否则三个月后没人说得清那次「误报」到底是什么。</p><p><span class="marginnote">数字实例：窗口长度就是「多快知道」与「多稳」的交换。按天开窗，漂移当天就能抓到，但周末效应都能触发误报；按 30 天开窗，报警很稳，可模型要多带伤跑一个月才被确认。常见做法是两层并行：短窗抓急变、长窗确认趋势，两层都亮灯才升级处置。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>更新应由证据触发：漂移检测是生产环的触发器，没有它就是盲目排班或永不更新。</li><li>指标变差有三种死因：世界变、模型变、管线变，冻结影子模型切开前两种。</li><li>监控分三层：输入、输出、性能；输入先动性能后动，只看性能层必然迟到。</li><li>统计设定决定质量：窗口长度、滞后阈值、多重检验校正，是把检验变成设备的螺丝。</li><li>检测必须绑定响应预案与台账，否则只是仪表盘装饰。</li><li>出处：Gama 等 2014 的漂移综述；Bifet 与 Gavaldà 2007（ADWIN）；Page 1954 的连续检验谱系。</li></ul>',6))])}const u=o(D,[["render",p]]);export{T as __pageData,u as default};
